// Parser et valider le JSON retourné par l'agent optimiseur
const raw = $json.output || "";

let parsed;
try {
  const clean = raw
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();
  parsed = JSON.parse(clean);
} catch (e) {
  return [{
    json: {
      is_valid: false,
      message: "non pas correct",
      reason: "Impossible de parser le JSON de l'agent : " + e.message
    }
  }];
}

// Vérification des champs obligatoires
const missingFields = [];
if (!parsed.status_final) missingFields.push("status_final");
if (parsed.quality_score === undefined || parsed.quality_score === null) missingFields.push("quality_score");
if (!parsed.hook) missingFields.push("hook");
if (!parsed.call_to_action) missingFields.push("call_to_action");
if (!parsed.post_final) missingFields.push("post_final");
if (!Array.isArray(parsed.ameliorations_appliquees)) missingFields.push("ameliorations_appliquees");
if (!parsed.resume_optimisation) missingFields.push("resume_optimisation");

if (missingFields.length > 0) {
  return [{
    json: {
      is_valid: false,
      message: "non pas correct",
      reason: "Champs manquants : " + missingFields.join(", ")
    }
  }];
}

// Vérification longueur du post
const postText = parsed.post_final.trim();
const wordCount = postText.split(/\s+/).filter(Boolean).length;

if (wordCount < 80) {
  return [{
    json: {
      is_valid: false,
      message: "non pas correct",
      reason: "Post trop court : " + wordCount + " mots (minimum 80)"
    }
  }];
}

// Vérification question finale
if (!postText.includes("?")) {
  return [{
    json: {
      is_valid: false,
      message: "non pas correct",
      reason: "Le post ne contient pas de question finale avec ?"
    }
  }];
}

// Vérification score
if (Number(parsed.quality_score) < 7) {
  return [{
    json: {
      is_valid: false,
      message: "non pas correct",
      reason: "Score trop faible : " + parsed.quality_score + "/10 (minimum 7)"
    }
  }];
}

// Tout est valide
return [{
  json: {
    is_valid: true,
    message: "correct",
    score: parsed.quality_score,
    post_to_publish: postText,
    hook: parsed.hook,
    call_to_action: parsed.call_to_action
  }
}];

